'use client';
import React,{useState,useEffect,useRef} from 'react';
import {Home,BookOpen,Layers,ShoppingBasket,FlaskConical,Heart,Settings,Plus,Search,ArrowUpRight,ArrowRight,ChevronRight,ChevronLeft,Clock,MoreHorizontal,X,Check,Trash2,Copy,Printer,Upload,Download,ImagePlus,GripVertical,ChefHat,Scale,Leaf,Cloud,RefreshCw,LogOut,Menu,ChevronDown,ArrowUp,ArrowDown,Sparkles,CakeSlice,Flower2,CheckCircle2,NotebookPen} from 'lucide-react';
import {RecordData,Part,Ingredient,uid,part,ingredient,newRecord,categories,componentCategories,statuses,fmt,num,aggregate,parseText,photo,DEMO} from './domain';
import {extractPdf,recipePdf} from './pdf';
const nav=[['Главная',Home],['Мои рецепты',BookOpen],['Компоненты',Layers],['Список покупок',ShoppingBasket],['Лаборатория',FlaskConical]] as const;
const titleMap:Record<string,string>={'Главная':'Моя кондитерская книга','Мои рецепты':'Мои рецепты','Компоненты':'Библиотека компонентов','Список покупок':'Список покупок','Лаборатория':'Кондитерская лаборатория','Избранное':'Мои любимые рецепты','Настройки':'Настройки'};
const copy=<T,>(v:T):T=>JSON.parse(JSON.stringify(v));
const date=(s:string)=>new Date(s).toLocaleDateString('ru-RU',{day:'numeric',month:'long'});
const Button=({children,onClick,soft=false,...props}:any)=><button className={'btn '+(soft?'soft':'primary')} onClick={onClick} {...props}>{children}</button>;
function Field({label,children}:any){return <label className="field"><span>{label}</span>{children}</label>}
function Empty({title='Здесь начинается ваша коллекция',text='Сохраните первый рецепт — и вдохновение всегда будет под рукой.',action,label='Добавить рецепт'}:any){return <div className="empty"><div className="empty-icon"><BookOpen size={31}/></div><h2>{title}</h2><p>{text}</p>{action&&<Button onClick={action}><Plus size={17}/>{label}</Button>}</div>}
export default function Kitchen(){
const [page,setPage]=useState('Главная'),[records,setRecords]=useState<RecordData[]>([]),[loaded,setLoaded]=useState(false),[loading,setLoading]=useState(true),[error,setError]=useState(''),[toast,setToast]=useState(''),[busy,setBusy]=useState(false),[email,setEmail]=useState(''),[demo,setDemo]=useState(false),[menu,setMenu]=useState(false);
const [search,setSearch]=useState(''),[category,setCategory]=useState('Все категории'),[status,setStatus]=useState('Все статусы'),[sort,setSort]=useState('updated'),[since,setSince]=useState(''),[dateField,setDateField]=useState('updated');
const [editor,setEditor]=useState<RecordData|null>(null),[detail,setDetail]=useState<RecordData|null>(null),[importOpen,setImportOpen]=useState(false),[importText,setImportText]=useState(''),[selectedList,setSelectedList]=useState(''),[recipePicker,setRecipePicker]=useState(false),[chosen,setChosen]=useState<Record<string,number>>({}),[factor,setFactor]=useState(1),[cooking,setCooking]=useState(false),[checks,setChecks]=useState<string[]>([]),[activePart,setActivePart]=useState(0),[lightbox,setLightbox]=useState(''),[confirm,setConfirm]=useState<{text:string;action:()=>void}|null>(null),[installPrompt,setInstallPrompt]=useState<any>(null),[restore,setRestore]=useState<RecordData[]|null>(null);
const restoreInput=useRef<HTMLInputElement>(null);const settings=records.find(r=>r.kind==='settings');const recipeCats=settings?.categories||categories;const compCats=settings?.componentCategories||componentCategories;const units=settings?.units||['г','кг','мл','л','шт'];
const ownRecipes=records.filter(r=>r.kind==='recipe'),recipes=demo?DEMO:ownRecipes,components=records.filter(r=>r.kind==='component'),lists=records.filter(r=>r.kind==='list'),labs=records.filter(r=>r.kind==='lab');
const list=lists.find(l=>l.id===selectedList)||lists[0];
function tell(t:string){setToast(t);setTimeout(()=>setToast(''),4000)}
async function load(){setLoading(true);setError('');try{const r=await fetch('/api/records',{cache:'no-store'});const data:any=await r.json();if(!r.ok)throw Error(data.error);setRecords(data.records);setEmail(data.email);setLoaded(true);}catch(e:any){setError(e.message||'Нет связи с сервером')}finally{setLoading(false)}}
useEffect(()=>{load();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});const handler=(e:any)=>{e.preventDefault();setInstallPrompt(e)};window.addEventListener('beforeinstallprompt',handler);return()=>window.removeEventListener('beforeinstallprompt',handler)},[]);
useEffect(()=>{const reload=()=>{if(!editor&&!busy)load()};window.addEventListener('focus',reload);return()=>window.removeEventListener('focus',reload)},[editor,busy]);
useEffect(()=>{let sentinel:any;let cancelled=false;if(cooking&&(navigator as any).wakeLock){(navigator as any).wakeLock.request('screen').then((s:any)=>{if(cancelled)s.release();else sentinel=s}).catch(()=>{});}return()=>{cancelled=true;sentinel?.release()}},[cooking]);
async function save(r:RecordData,quiet=false){setBusy(true);try{const data={...r};if(data.id.startsWith('demo-')){data.id=uid();delete data.revision;data.created=new Date().toISOString()}const res=await fetch('/api/records',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const v:any=await res.json();if(!res.ok)throw Error(v.error);setRecords(prev=>[...prev.filter(p=>p.id!==v.id),v]);if(!quiet)tell('Сохранено в вашей коллекции');return v as RecordData;}catch(e:any){tell(e.message||'Не удалось сохранить');return null}finally{setBusy(false)}}
async function remove(r:RecordData){if(r.id.startsWith('demo-')){tell('Это демонстрационный пример');return}setConfirm({text:`Удалить «${r.name}»? Это действие нельзя отменить.`,action:async()=>{setBusy(true);try{const res=await fetch('/api/records',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:r.id,revision:r.revision})});const v:any=await res.json();if(!res.ok)throw Error(v.error);setRecords(p=>p.filter(x=>x.id!==r.id));setDetail(null);tell('Удалено')}catch(e:any){tell(e.message)}finally{setBusy(false)}}})}
function go(p:string){setPage(p);setMenu(false);setSearch('');setCategory('Все категории');setStatus('Все статусы');setSince('');setDetail(null);setCooking(false)}
function edit(r:RecordData){setEditor(copy(r));setDetail(null)}
function open(r:RecordData){setDetail(copy(r));setFactor(1);setChecks([]);setActivePart(0);setCooking(false)}
function duplicate(r:RecordData){const v={...copy(r),id:uid(),name:r.name+' — копия',created:new Date().toISOString()};delete v.revision;setEditor(v);setDetail(null)}
async function favorite(r:RecordData){if(r.id.startsWith('demo-')){tell('Сначала сохраните пример в личную коллекцию');return}const v=await save({...r,favorite:!r.favorite},true);if(v&&detail?.id===r.id)setDetail(v)}
function filterRows(rows:RecordData[]){return rows.filter(r=>(category==='Все категории'||r.category===category)&&(status==='Все статусы'||r.status===status)&&(!since||r[dateField]?.slice(0,10)>=since)&&[r.name,r.description,r.category,...(r.parts||[]).flatMap((p:Part)=>[p.name,...p.ingredients.map(i=>i.name)])].join(' ').toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'ru'):String(b[sort]).localeCompare(String(a[sort])))}
function exportData(data:any,name:string){const blob=new Blob([JSON.stringify({format:'konditerka',version:1,records:data},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function photoUpload(file:File){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>25*1024*1024){tell('Выберите JPG, PNG или WebP до 25 МБ');return ''}setBusy(true);try{const bitmap=await createImageBitmap(file);const ratio=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=bitmap.width*ratio;canvas.height=bitmap.height*ratio;canvas.getContext('2d')!.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const blob=await new Promise<Blob|null>(resolve=>canvas.toBlob(resolve,'image/jpeg',0.86));if(!blob)throw Error('Не удалось обработать фотографию');const form=new FormData();form.append('photo',blob,'photo.jpg');const r=await fetch('/api/photos',{method:'POST',body:form});const v:any=await r.json();if(!r.ok)throw Error(v.error);return v.url;}catch(e:any){tell(e.message);return ''}finally{setBusy(false)}}
async function downloadPdf(r:RecordData){setBusy(true);try{await recipePdf(r,factor)}catch(e:any){tell(e.message||'Не удалось создать PDF')}finally{setBusy(false)}}
async function addToShopping(selection:{recipe:RecordData;factor:number}[]){let target=list;if(!target)target=newRecord('list');const fresh=aggregate(selection);if(!fresh.length){tell('В выбранных рецептах нет ингредиентов');return}if(!target.name)target.name='Покупки для десертов';const merged=aggregate([{recipe:{parts:[{ingredients:[...(target.items||[]).map((i:any)=>({name:i.name,qty:i.qty,unit:i.unit})),...fresh]}]} as any,factor:1}]).map((i:any)=>{const prev=(target!.items||[]).find((p:any)=>p.name.trim().toLowerCase()===i.name.trim().toLowerCase()&&((p.unit==='кг'?'г':p.unit==='л'?'мл':p.unit)===i.unit));return {...i,have:prev?(prev.have||0)*(prev.unit==='кг'||prev.unit==='л'?1000:1):0,bought:false}});const result=await save({...target,items:merged});if(result){setSelectedList(result.id);setRecipePicker(false);setDetail(null);setPage('Список покупок');setDemo(false)}}
function Card({r}:any){return <article className="recipe-card"><div className="card-photo" onClick={()=>open(r)} role="button" tabIndex={0} onKeyDown={e=>e.key==='Enter'&&open(r)}>{r.image?<img src={r.image} alt={r.name}/>:<div className="photo-placeholder"><CakeSlice size={46}/></div>}<span className={'badge '+(r.status==='Готовый рецепт'?'green':r.status==='На тестировании'?'cream':'pink')}>{r.status}</span><button className={'heart '+(r.favorite?'active':'')} aria-label="В избранное" onClick={e=>{e.stopPropagation();favorite(r)}}><Heart size={17} fill={r.favorite?'currentColor':'none'}/></button></div><div className="card-body" onClick={()=>open(r)}><div className="eyebrow">{r.category}</div><h3>{r.name}</h3><div className="card-meta"><span><Clock size={13}/> {r.time||'Время не указано'}</span><span>{date(r.updated)}</span></div></div></article>}
function Cards({rows}:any){return rows.length?<div className="recipe-grid">{rows.map((r:RecordData)=><Card r={r} key={r.id}/>)}</div>:<Empty action={()=>setEditor(newRecord(page==='Компоненты'?'component':'recipe'))}/>}
function UploadField({onPhoto,label='Добавить фотографии'}:any){return <label className="upload-btn"><ImagePlus size={17}/>{busy?'Загрузка…':label}<input type="file" accept="image/jpeg,image/png,image/webp" disabled={busy} onChange={async e=>{const f=e.target.files?.[0];if(f){const url=await photoUpload(f);if(url)onPhoto(url)}e.target.value=''}}/></label>}
function HeaderSection({title,subtitle,action}:any){return <div className="section-head"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>}
const currentRows=page==='Компоненты'?components:page==='Избранное'?recipes.filter(r=>r.favorite):recipes;
return <div className={'app '+(cooking?'is-cooking':'')}>
<aside className={'sidebar '+(menu?'mobile-open':'')}><a className="brand" href="/" onClick={e=>{e.preventDefault();go('Главная')}}><span className="brand-mark"><ChefHat size={27} strokeWidth={1.3}/></span>Кондитерка<span className="brand-dot">.</span></a><div className="brand-sub">ЛИЧНАЯ КНИГА РЕЦЕПТОВ</div><div className="nav-label">МОЁ ПРОСТРАНСТВО</div><nav>{nav.map(([p,Icon])=><button className={page===p?'selected':''} onClick={()=>go(p)} key={p}><Icon size={20} strokeWidth={1.5}/>{p}{p==='Мои рецепты'&&<span className="nav-count">{recipes.length}</span>}</button>)}<div className="nav-divider"/><button className={page==='Избранное'?'selected':''} onClick={()=>go('Избранное')}><Heart size={20} strokeWidth={1.5}/>Избранное</button><button className={page==='Настройки'?'selected':''} onClick={()=>go('Настройки')}><Settings size={20} strokeWidth={1.5}/>Настройки</button></nav><div className="sidebar-note"><Flower2 size={30} strokeWidth={1}/><p>Немного вдохновения.<br/>Щепотка волшебства.<br/>Ваш идеальный десерт.</p><span>СОЗДАНО С ЛЮБОВЬЮ</span></div><button className="profile" onClick={()=>go('Настройки')}><span className="avatar">{(settings?.profile||'Моя кухня')[0]}</span><span><b>{settings?.profile||'Моя кондитерская'}</b><small>Личное пространство</small></span><ChevronRight size={15}/></button></aside>
<div className="workspace"><header className="topbar"><button className="mobile-menu icon-btn" aria-label="Открыть меню" onClick={()=>setMenu(!menu)}><Menu size={23}/></button><div className="breadcrumb">Моё пространство <ChevronRight size={13}/><b>{page}</b></div><div className="top-actions"><span className={'cloud-state '+(error?'danger':'')}><Cloud size={15}/>{loading?'Загрузка…':error?'Нет связи':'Сохранено в облаке'}</span><button className="top-add" onClick={()=>setEditor(newRecord('recipe'))}><Plus size={17}/><span>Добавить рецепт</span></button><button className="avatar small" aria-label="Профиль" onClick={()=>go('Настройки')}>{(settings?.profile||'К')[0]}</button></div></header>
<main><div className="page-title"><div><div className="eyebrow">ВАШЕ ВДОХНОВЕНИЕ — В КАЖДОЙ ДЕТАЛИ</div><h1>{titleMap[page]}</h1><p>{page==='Главная'?'Моя коллекция рецептов и кондитерских вдохновений':page==='Компоненты'?'Проверенные основы для ваших новых десертов':page==='Лаборатория'?'От первой идеи до идеального вкуса':page==='Список покупок'?'Всё необходимое для ваших сладких планов':'Всё любимое, бережно сохранённое в одном месте'}</p></div>{page!=='Настройки'&&page!=='Главная'&&<Button onClick={()=>page==='Список покупок'?setEditor(newRecord('list')):setEditor(newRecord(page==='Лаборатория'?'lab':page==='Компоненты'?'component':'recipe'))}><Plus size={17}/>{page==='Лаборатория'?'Новая разработка':page==='Компоненты'?'Создать компонент':page==='Список покупок'?'Новый список':'Добавить рецепт'}</Button>}</div>
{error&&<div className="notice error"><span>{error}</span><button onClick={load}><RefreshCw size={15}/>Повторить</button><a href="/login" target="_top">Войти</a></div>}
{demo&&<div className="demo-banner"><span><Sparkles size={15}/> Демонстрационная коллекция · примеры не сохранены</span><button onClick={()=>{setDemo(false);tell('Открыта ваша личная коллекция')}}>Перейти к моей коллекции <ArrowRight size={14}/></button></div>}
{page==='Главная'&&<>
<section className="hero"><div className="hero-content"><div className="hero-kicker"><span/> МЕСТО ДЛЯ СЛАДКИХ ИДЕЙ</div><h2>Здесь рождаются<br/>ваши сладкие истории<span>…</span></h2><p>Храните любимые рецепты, исследуйте новые вкусы<br className="desktop"/> и создавайте десерты с вашим характером.</p><Button onClick={()=>setEditor(newRecord('recipe'))}><Plus size={17}/>Создать новый рецепт</Button><div className="hero-caption">От вдохновения — к совершенству</div></div><div className="hero-image"><img src={photo('photo-1488477181946-6428a0291777',1200)} alt="Нежный ягодный десерт в французском стиле"/><span className="image-note"><Leaf size={16}/> Вдохновение в простых вещах</span></div></section>
<div className="stats">{[[BookOpen,recipes.length,'Рецептов в коллекции','pink'],[CakeSlice,recipes.filter(r=>r.status==='Готовый рецепт').length,'Авторских десертов','cream'],[FlaskConical,recipes.filter(r=>r.status!=='Готовый рецепт').length,'В разработке','green'],[Heart,recipes.filter(r=>r.favorite).length,'Любимых рецептов','beige']].map(([Icon,n,label,color]:any)=><div className="stat" key={label}><span className={'stat-icon '+color}><Icon size={22} strokeWidth={1.3}/></span><div><strong>{n}</strong><small>{label}</small></div></div>)}</div>
<div className="quick-actions">{[[Plus,'Добавить рецепт',()=>setEditor(newRecord('recipe'))],[Layers,'Создать компонент',()=>setEditor(newRecord('component'))],[ShoppingBasket,'Список покупок',()=>go('Список покупок')],[FlaskConical,'Новая разработка',()=>setEditor(newRecord('lab'))]].map(([Icon,label,fn]:any)=><button key={label} onClick={fn}><Icon size={19} strokeWidth={1.4}/>{label}<ArrowUpRight size={15}/></button>)}</div>
<HeaderSection title="Последние рецепты" subtitle="Ваши маленькие шедевры и новые открытия" action={<button className="text-link" onClick={()=>go('Мои рецепты')}>Все рецепты <ArrowRight size={16}/></button>}/>
{loading&&!loaded?<div className="loading">Загружаем вашу книгу…</div>:recipes.length?<Cards rows={[...recipes].sort((a,b)=>b.updated.localeCompare(a.updated)).slice(0,4)}/>:<div className="first-collection"><Empty action={()=>setEditor(newRecord('recipe'))}/><button className="text-link" onClick={()=>setDemo(true)}>Посмотреть демонстрационную коллекцию <ArrowRight size={16}/></button></div>}
<HeaderSection title="По страницам кондитерской книги" action={<button className="text-link" onClick={()=>go('Мои рецепты')}>Все категории <ArrowRight size={16}/></button>}/><div className="categories">{[[CakeSlice,'Торты','pink'],[Flower2,'Муссовые десерты','green'],[ChefHat,'Тарталетки и тарты','cream'],[Leaf,'Шу и эклеры','beige'],[Heart,'Макарон','pink']].map(([Icon,c,color]:any)=><button key={c} className={color} onClick={()=>{go('Мои рецепты');setCategory(c)}}><Icon size={29} strokeWidth={1}/><span>{c}</span><small>{recipes.filter(r=>r.category===c).length} рецептов</small></button>)}</div>
<div className="bottom-note"><span>«</span><p>Самый важный ингредиент — вдохновение.</p><Flower2 size={23} strokeWidth={1}/></div>
</>}
{['Мои рецепты','Компоненты','Избранное'].includes(page)&&<><div className="filterbar"><div className="search"><Search size={18}/><input aria-label="Поиск" placeholder="Название, ингредиент или компонент…" value={search} onChange={e=>setSearch(e.target.value)}/></div><select aria-label="Категория" value={category} onChange={e=>setCategory(e.target.value)}><option>Все категории</option>{(page==='Компоненты'?compCats:recipeCats).map((c:string)=><option key={c}>{c}</option>)}</select><select aria-label="Статус" value={status} onChange={e=>setStatus(e.target.value)}><option>Все статусы</option>{statuses.map(s=><option key={s}>{s}</option>)}</select><select aria-label="Сортировка" value={sort} onChange={e=>setSort(e.target.value)}><option value="updated">Сначала изменённые</option><option value="created">Сначала новые</option><option value="name">По алфавиту</option></select></div><div className="collection-meta"><span>{filterRows(currentRows).length} записей</span><div className="date-filter"><select aria-label="Фильтр по дате" value={dateField} onChange={e=>setDateField(e.target.value)}><option value="updated">Изменены с</option><option value="created">Созданы с</option></select><input type="date" aria-label="Начиная с даты" value={since} onChange={e=>setSince(e.target.value)}/>{page!=='Компоненты'&&<button className="text-link" onClick={()=>setImportOpen(true)}><Upload size={15}/>Импорт рецепта</button>}</div></div><Cards rows={filterRows(currentRows)}/></>}
{page==='Список покупок'&&<>{!lists.length?<Empty title="Всё начинается с хорошего списка" text="Добавьте продукты вручную или соберите их из ваших рецептов." label="Создать список покупок" action={()=>setEditor(newRecord('list'))}/>:<><div className="list-tabs">{lists.map(l=><button className={l.id===list?.id?'selected':''} onClick={()=>setSelectedList(l.id)} key={l.id}>{l.name}<span>{l.items.filter((i:any)=>!i.bought).length}</span></button>)}</div>{list&&<div className="shopping-sheet"><HeaderSection title={list.name} subtitle={'Создан '+date(list.created)} action={<div className="flex"><button className="icon-btn" aria-label="Редактировать список" onClick={()=>edit(list)}><NotebookPen size={18}/></button><button className="icon-btn" aria-label="Дублировать список" onClick={()=>duplicate(list)}><Copy size={18}/></button><button className="icon-btn" aria-label="Удалить список" onClick={()=>remove(list)}><Trash2 size={18}/></button></div>}/><div className="shopping-toolbar"><Button onClick={()=>{setChosen({});setRecipePicker(true)}}><Plus size={16}/>Добавить из рецептов</Button><Button soft onClick={()=>edit(list)}><Plus size={16}/>Добавить вручную</Button><button className="text-link" disabled={busy} onClick={()=>setConfirm({text:'Очистить все купленные позиции?',action:()=>save({...list,items:list.items.filter((i:any)=>!i.bought)})})}>Очистить купленное</button></div><div className="shopping-progress"><span style={{width:`${list.items.length?list.items.filter((i:any)=>i.bought).length/list.items.length*100:0}%`}}/></div><p className="muted">Куплено {list.items.filter((i:any)=>i.bought).length} из {list.items.length} · Количество «уже есть» указывается в единицах позиции</p>{[...new Set<string>(list.items.map((i:any)=>i.category||'Другое'))].map(c=><section className="shopping-group" key={c}><div className="eyebrow">{c}</div>{list.items.filter((i:any)=>(i.category||'Другое')===c).map((i:any)=><div className={'shopping-item '+(i.bought?'bought':'')} key={i.id}><button className={'checkbox '+(i.bought?'checked':'')} aria-label={'Куплено: '+i.name} disabled={busy} onClick={()=>save({...list,items:list.items.map((x:any)=>x.id===i.id?{...x,bought:!x.bought}:x)},true)}>{i.bought&&<Check size={15}/>}</button><div className="item-name"><b>{i.name}</b><small>Необходимо: {fmt(i.qty)} {i.unit}</small></div><label className="have">Уже есть<input type="number" min="0" step="any" defaultValue={i.have||0} key={i.id+'-'+i.have} onBlur={e=>{const have=num(e.target.value);if(have>=0&&Number.isFinite(have)&&have!==(i.have||0))save({...list,items:list.items.map((x:any)=>x.id===i.id?{...x,have}:x)},true)}}/></label><strong className="need">{fmt(Math.max(0,i.qty-(i.have||0)))} <small>{i.unit}</small></strong><button className="icon-btn" aria-label="Удалить продукт" disabled={busy} onClick={()=>save({...list,items:list.items.filter((x:any)=>x.id!==i.id)},true)}><X size={16}/></button></div>)}</section>)}{!list.items.length&&<p className="empty-small">В списке пока нет продуктов. Добавьте их из рецептов или вручную.</p>}</div>}</>}</>}
{page==='Лаборатория'&&<>{!labs.length?<Empty title="Место для вкусных экспериментов" text="Записывайте идеи, сохраняйте тесты и находите идеальный баланс." label="Начать разработку" action={()=>setEditor(newRecord('lab'))}/>:<div className="lab-grid">{labs.map(l=><article className="lab-card" key={l.id}><div className="flex between"><span className="badge green"><FlaskConical size={13}/> {l.approved?'Рецептура утверждена':'Творческий процесс'}</span><button className="icon-btn" aria-label="Удалить разработку" onClick={()=>remove(l)}><Trash2 size={16}/></button></div><h2>{l.name}</h2><p>{l.idea||l.description}</p><div className="flavors">{l.flavors}</div><div className="lab-bottom"><span>{l.tests?.length||0} тестов · {date(l.updated)}</span><button className="text-link" onClick={()=>edit(l)}>Открыть дневник <ArrowRight size={16}/></button></div></article>)}</div>}</>}
{page==='Настройки'&&<div className="settings-grid"><section className="sheet"><h2>Моя кондитерская</h2><p className="muted">{email||'Войдите в аккаунт для сохранения'}</p><Field label="Имя в личном пространстве"><input defaultValue={settings?.profile||''} placeholder="Как называется ваша кухня?" onBlur={e=>{if(e.target.value!==settings?.profile)save({...newRecord('settings'),...settings,name:'Настройки',profile:e.target.value})}}/></Field><div className="notice">Вход по вашей электронной почте и паролю. Регистрации для посторонних нет. База и фотографии хранятся на вашем сервере.</div><a className="btn soft" href="/logout" target="_top"><LogOut size={16}/>Выйти из аккаунта</a><PasswordForm tell={tell}/><h3>Установить приложение</h3><p className="muted">На телефоне откройте меню браузера и выберите «На экран Домой» или «Установить приложение».</p>{installPrompt&&<Button onClick={async()=>{await installPrompt.prompt();setInstallPrompt(null)}}>Установить «Кондитерку»</Button>}</section><section className="sheet"><h2>Ваша коллекция в безопасности</h2><p className="muted">Рецепты, компоненты и списки хранятся в облаке. Для личного архива сохраните резервную копию.</p><Button soft disabled={!loaded} onClick={()=>exportData(records,'Кондитерка — резервная копия')}><Download size={16}/>Экспорт всей коллекции</Button><Button soft onClick={()=>exportData(ownRecipes,'Кондитерка — рецепты')}><Download size={16}/>Экспорт рецептов</Button><Button soft onClick={()=>restoreInput.current?.click()}><Upload size={16}/>Восстановить из копии</Button><input ref={restoreInput} hidden type="file" accept="application/json,.json" onChange={async e=>{try{const f=e.target.files?.[0];if(!f)return;const v=JSON.parse(await f.text());if(v.format!=='konditerka'||v.version!==1||!Array.isArray(v.records)||v.records.length>1000||v.records.some((r:any)=>!['recipe','component','lab','list','settings'].includes(r.kind)||typeof r.name!=='string'))throw Error();setRestore(v.records)}catch{tell('Не удалось прочитать резервную копию «Кондитерки»')}e.target.value=''}}/><p className="muted small-text">Копия содержит ссылки на фотографии в облаке. Для независимого архива также сохраните оригиналы фотографий.</p><button className="text-link" onClick={load}><RefreshCw size={15}/>Обновить с сервера</button></section><section className="sheet wide"><h2>Категории и единицы измерения</h2><p className="muted">Изменение справочника не изменяет сохранённые рецептуры.</p>{[['Категории рецептов','categories',recipeCats],['Категории компонентов','componentCategories',compCats],['Единицы измерения','units',units]].map(([label,key,values]:any)=><div className="dictionary" key={key}><h3>{label}</h3><div className="tags">{values.map((v:string,i:number)=><span key={v}><input aria-label={v} defaultValue={v} onBlur={e=>{const next=e.target.value.trim();if(next&&next!==v&&!values.includes(next))save({...newRecord('settings'),...settings,name:'Настройки',[key]:values.map((s:string,j:number)=>j===i?next:s)})}}/><button aria-label={'Удалить '+v} onClick={()=>setConfirm({text:'Удалить «'+v+'» из справочника?',action:()=>save({...newRecord('settings'),...settings,name:'Настройки',[key]:values.filter((s:string)=>s!==v)})})}><X size={13}/></button></span>)}</div><form className="inline-form" onSubmit={e=>{e.preventDefault();const f=e.currentTarget;const v=(new FormData(f).get('value') as string).trim();if(v&&!values.includes(v))save({...newRecord('settings'),...settings,name:'Настройки',[key]:[...values,v]});f.reset()}}><input name="value" required placeholder="Новое значение"/><Button soft type="submit"><Plus size={16}/>Добавить</Button></form></div>)}</section></div>}
<footer>Кондитерка <span>·</span> Ваши рецепты. Ваше вдохновение. Ваша история.<Flower2 size={16} strokeWidth={1}/></footer>
</main></div>
<nav className="bottom-nav">{nav.map(([p,Icon])=><button className={page===p?'active':''} onClick={()=>go(p)} key={p}><Icon size={21}/><span>{p==='Мои рецепты'?'Рецепты':p==='Список покупок'?'Покупки':p}</span></button>)}</nav>
{toast&&<div className="toast" role="status"><CheckCircle2 size={18}/>{toast}</div>}
{editor&&<div className="modal-backdrop"><div className="modal editor-modal" role="dialog" aria-modal="true" aria-label="Редактирование"><div className="modal-head"><div><div className="eyebrow">{editor.kind==='lab'?'ДНЕВНИК РАЗРАБОТКИ':editor.kind==='list'?'ПЛАНИРУЕМ ПОКУПКИ':'ВАША КОНДИТЕРСКАЯ КНИГА'}</div><h2>{editor.name||({recipe:'Новый рецепт',component:'Новый компонент',list:'Новый список',lab:'Новая разработка'} as any)[editor.kind]}</h2></div><button className="icon-btn" aria-label="Закрыть редактор" onClick={()=>setConfirm({text:'Закрыть редактор без сохранения изменений?',action:()=>setEditor(null)})}><X size={23}/></button></div><form onSubmit={async e=>{e.preventDefault();if(!editor.name.trim()){tell('Введите название');return;}const v=await save(editor);if(v){setEditor(null);setDemo(false);if(v.kind==='list'){setSelectedList(v.id);setPage('Список покупок')}else if(v.kind==='lab')setPage('Лаборатория');else{setPage(v.kind==='component'?'Компоненты':'Мои рецепты');open(v)}}}}><div className="modal-content"><div className="form-grid"><Field label="Название *"><input required maxLength={200} placeholder="Например, фисташковый тарт с малиной" value={editor.name} onChange={e=>setEditor({...editor,name:e.target.value})}/></Field>{['recipe','component'].includes(editor.kind)&&<><Field label="Категория"><select value={editor.category} onChange={e=>setEditor({...editor,category:e.target.value})}>{(editor.kind==='component'?compCats:recipeCats).map((c:string)=><option key={c}>{c}</option>)}</select></Field><Field label="Статус"><select value={editor.status} onChange={e=>setEditor({...editor,status:e.target.value})}>{statuses.map(s=><option key={s}>{s}</option>)}</select></Field><Field label="Количество порций / изделий"><input type="number" min="0.001" step="any" required value={editor.servings} onChange={e=>setEditor({...editor,servings:num(e.target.value)})}/></Field></>}</div>
{editor.kind!=='list'&&<Field label={editor.kind==='lab'?'Концепция десерта':'Описание'}><textarea rows={3} value={editor.description} onChange={e=>setEditor({...editor,description:e.target.value})} placeholder="Что делает этот десерт особенным?"/></Field>}
{['recipe','component'].includes(editor.kind)&&<><div className="photo-editor">{editor.image&&<div className="photo-thumb"><img src={editor.image} alt="Главная фотография"/><button aria-label="Удалить главное фото" onClick={()=>setEditor({...editor,image:''})} type="button"><X size={13}/></button></div>}<UploadField label={editor.image?'Изменить главное фото':'Добавить главное фото'} onPhoto={(url:string)=>setEditor({...editor,image:url})}/>{editor.photos?.map((url:string,i:number)=><div className="photo-thumb" key={i}><img src={url} alt={'Фото '+(i+1)} onClick={()=>setLightbox(url)}/><button aria-label="Удалить фото" type="button" onClick={()=>setEditor({...editor,photos:editor.photos.filter((_:any,j:number)=>i!==j)})}><X size={13}/></button></div>)}<UploadField label="В галерею" onPhoto={(url:string)=>setEditor({...editor,photos:[...(editor.photos||[]),url]})}/></div><details className="parameters"><summary>Параметры, хранение и заметки <ChevronDown size={16}/></summary><div className="form-grid">{[['Вес готового изделия, г','weight'],['Диаметр формы, см','diameter'],['Размер формы','size'],['Время приготовления','time'],['Температура приготовления','temperature'],['Условия хранения','storage'],['Срок хранения','shelfLife'],['Выход готового продукта','yield']].map(([label,key])=><Field label={label} key={key}><input value={editor[key]||''} onChange={e=>setEditor({...editor,[key]:e.target.value})}/></Field>)}</div><Field label="Авторские заметки"><textarea value={editor.notes||''} onChange={e=>setEditor({...editor,notes:e.target.value})}/></Field></details><div className="section-head"><div><h2>Компоненты рецептуры</h2><p>Каждый вкус — на своём месте</p></div></div>{editor.parts.map((p:Part,index:number)=><PartEditor key={p.id} p={p} index={index} total={editor.parts.length} units={units} UploadField={UploadField} onChange={(next:Part)=>setEditor({...editor,parts:editor.parts.map((v:Part,i:number)=>i===index?next:v)})} onMove={(direction:number)=>{const parts=[...editor.parts];[parts[index],parts[index+direction]]=[parts[index+direction],parts[index]];setEditor({...editor,parts})}} onDelete={()=>setConfirm({text:'Удалить компонент «'+p.name+'» из этой рецептуры?',action:()=>setEditor({...editor,parts:editor.parts.filter((_:any,i:number)=>i!==index)})})}/>)}<div className="flex wrap"><Button type="button" soft onClick={()=>setEditor({...editor,parts:[...editor.parts,part()]})}><Plus size={16}/>Новый компонент</Button>{editor.kind==='recipe'&&<select aria-label="Добавить из библиотеки" value="" onChange={e=>{const c=components.find(c=>c.id===e.target.value);if(c)setEditor({...editor,parts:[...editor.parts,...copy(c.parts).map((p:Part)=>({...p,id:uid(),sourceId:c.id,sourceRevision:c.revision,name:c.name+(c.parts.length>1?' · '+p.name:'')}))]})}}><option value="">Добавить из библиотеки…</option>{components.map(c=><option value={c.id} key={c.id}>{c.name} · версия {c.revision}</option>)}</select>}</div></>}
{editor.kind==='list'&&<><p className="muted">Количество «уже есть» можно указать после сохранения списка.</p>{editor.items.map((i:any,index:number)=><div className="manual-item" key={i.id}><input required aria-label="Название продукта" placeholder="Продукт" value={i.name} onChange={e=>setEditor({...editor,items:editor.items.map((v:any,j:number)=>j===index?{...v,name:e.target.value}:v)})}/><input aria-label="Количество" type="number" step="any" min="0.000001" required value={i.qty} onChange={e=>setEditor({...editor,items:editor.items.map((v:any,j:number)=>j===index?{...v,qty:num(e.target.value)}:v)})}/><select aria-label="Единица измерения" value={i.unit} onChange={e=>setEditor({...editor,items:editor.items.map((v:any,j:number)=>j===index?{...v,unit:e.target.value}:v)})}>{units.map((u:string)=><option key={u}>{u}</option>)}</select><select aria-label="Категория продукта" value={i.category||'Другое'} onChange={e=>setEditor({...editor,items:editor.items.map((v:any,j:number)=>j===index?{...v,category:e.target.value}:v)})}>{['Молочные продукты','Шоколад и какао','Мука и сухие ингредиенты','Фрукты и ягоды','Орехи и пасты','Яйца','Упаковка','Другое'].map(s=><option key={s}>{s}</option>)}</select><button type="button" className="icon-btn" aria-label="Удалить продукт" onClick={()=>setEditor({...editor,items:editor.items.filter((_:any,j:number)=>index!==j)})}><X size={17}/></button></div>)}<Button soft type="button" onClick={()=>setEditor({...editor,items:[...editor.items,{id:uid(),name:'',qty:1,unit:'г',have:0,bought:false,category:'Другое'}]})}><Plus size={16}/>Добавить продукт</Button></>}
{editor.kind==='lab'&&<><div className="form-grid">{[['Идея','idea'],['Вкусовые сочетания','flavors'],['Предполагаемые компоненты','plannedParts'],['Заметки','notes']].map(([label,key])=><Field label={label} key={key}><textarea value={editor[key]||''} onChange={e=>setEditor({...editor,[key]:e.target.value})}/></Field>)}</div><div className="photo-editor">{(editor.photos||[]).map((url:string,i:number)=><div className="photo-thumb" key={i}><img src={url} alt="Вдохновение" onClick={()=>setLightbox(url)}/><button type="button" aria-label="Удалить фото" onClick={()=>setEditor({...editor,photos:editor.photos.filter((_:any,j:number)=>j!==i)})}><X size={13}/></button></div>)}<UploadField label="Фотографии вдохновения" onPhoto={(url:string)=>setEditor({...editor,photos:[...(editor.photos||[]),url]})}/></div><h2>История тестирования</h2>{editor.tests.map((t:any,index:number)=><div className="test-sheet" key={t.id}><div className="flex between"><h3>Тест №{index+1}</h3><input aria-label="Дата тестирования" type="date" value={t.date} onChange={e=>setEditor({...editor,tests:editor.tests.map((v:any,j:number)=>j===index?{...v,date:e.target.value}:v)})}/></div><Field label="Использованная рецептура — сохраняется отдельная версия"><select value={t.recipe?.id||''} onChange={e=>{const r=ownRecipes.find(r=>r.id===e.target.value);setEditor({...editor,tests:editor.tests.map((v:any,j:number)=>j===index?{...v,recipe:r?copy(r):null}:v)})}}><option value="">Выберите рецепт</option>{ownRecipes.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></Field>{t.recipe&&<p className="muted">Снимок: {t.recipe.name} · версия {t.recipe.revision||1} · {t.recipe.parts.length} компонентов</p>}<div className="form-grid">{[['Что получилось','result'],['Проблемы','problems'],['Что изменить','changes'],['Дегустация и заметки','notes']].map(([label,key])=><Field label={label} key={key}><textarea value={t[key]||''} onChange={e=>setEditor({...editor,tests:editor.tests.map((v:any,j:number)=>j===index?{...v,[key]:e.target.value}:v)})}/></Field>)}</div><div className="photo-editor">{(t.photos||[]).map((url:string,i:number)=><div className="photo-thumb" key={i}><img src={url} alt="Результат теста" onClick={()=>setLightbox(url)}/><button type="button" aria-label="Удалить фото теста" onClick={()=>setEditor({...editor,tests:editor.tests.map((v:any,j:number)=>j===index?{...v,photos:v.photos.filter((_:any,k:number)=>k!==i)}:v)})}><X size={13}/></button></div>)}<UploadField label="Фото результата" onPhoto={(url:string)=>setEditor({...editor,tests:editor.tests.map((v:any,j:number)=>j===index?{...v,photos:[...(v.photos||[]),url]}:v)})}/></div><Button type="button" soft disabled={!t.recipe||busy} onClick={()=>setConfirm({text:'Сохранить выбранную версию как готовый рецепт? История тестов останется в лаборатории.',action:async()=>{const r=await save({...copy(t.recipe),id:uid(),revision:undefined,name:editor.name,status:'Готовый рецепт',created:new Date().toISOString(),laboratoryId:editor.id});if(r){const updated=await save({...editor,approved:r.id});if(updated)setEditor(updated)}}})}><Check size={16}/>Утвердить рецептуру</Button></div>)}<Button soft type="button" onClick={()=>setEditor({...editor,tests:[...editor.tests,{id:uid(),date:new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Moscow'}),result:'',problems:'',changes:'',notes:'',photos:[]}]})}><Plus size={16}/>Добавить тест</Button></>}
</div><div className="modal-footer"><span><Cloud size={15}/> Сохранение в личную коллекцию</span><Button type="submit" disabled={busy||!loaded}>{busy?'Сохраняем…':'Сохранить'}<Check size={16}/></Button></div></form></div></div>}
{detail&&<div className="modal-backdrop"><article className={'modal detail-modal '+(cooking?'cooking-mode':'')} role="dialog" aria-modal="true" aria-label={detail.name}><div className="detail-top no-print"><span className="eyebrow">{cooking?'РЕЖИМ ПРИГОТОВЛЕНИЯ':'КАРТОЧКА РЕЦЕПТУРЫ'}</span><button className="icon-btn" aria-label="Закрыть рецепт" onClick={()=>{setDetail(null);setCooking(false)}}><X size={23}/></button></div><div className="detail-cover">{detail.image&&<img src={detail.image} alt={detail.name} onClick={()=>setLightbox(detail.image)}/>}<div><div className="eyebrow">{detail.category}</div><h1>{detail.name}</h1><p>{detail.description}</p><span className="badge green">{detail.status}</span><div className="detail-params">{[['Порции / изделия',detail.servings],['Выход',detail.yield],['Вес, г',detail.weight],['Диаметр, см',detail.diameter],['Форма',detail.size],['Время',detail.time],['Температура',detail.temperature]].filter(v=>v[1]).map(([label,value])=><span key={label}><small>{label}</small><b>{value}</b></span>)}</div></div></div><div className="detail-content"><div className="detail-actions no-print"><Button onClick={()=>{setCooking(!cooking);setChecks([])}}><ChefHat size={17}/>{cooking?'Завершить приготовление':'Готовить'}</Button><Button soft onClick={()=>edit(detail)}><NotebookPen size={16}/>Редактировать</Button><button className="icon-btn" aria-label="Дублировать" onClick={()=>duplicate(detail)}><Copy size={19}/></button><button className="icon-btn" aria-label="Избранное" onClick={()=>favorite(detail)}><Heart size={19} fill={detail.favorite?'currentColor':'none'}/></button><button className="icon-btn" aria-label="Печать и сохранение PDF" onClick={()=>window.print()}><Printer size={19}/></button><button className="icon-btn" aria-label="Скачать рецепт в PDF" disabled={busy} onClick={()=>downloadPdf(detail)}><Download size={19}/></button><button className="icon-btn" aria-label="Удалить рецепт" onClick={()=>remove(detail)}><Trash2 size={19}/></button></div><div className="calculator"><div className="flex between"><h3><Scale size={20}/>Пересчёт рецептуры</h3><span className="muted">Исходная рецептура сохранена</span></div><div className="calc-controls"><Field label="Коэффициент"><input type="number" min="0.000001" step="any" value={factor} onChange={e=>{const n=num(e.target.value);setFactor(Number.isFinite(n)&&n>=0?n:0)}}/></Field><Field label="Порций / изделий"><input type="number" min="0.000001" step="any" value={Number((detail.servings*factor).toFixed(6))} onChange={e=>setFactor(Math.max(0,num(e.target.value)/(detail.servings||1)))}/></Field><div className="factor-buttons">{[.5,1,1.5,2,3].map(n=><button className={n===factor?'active':''} onClick={()=>setFactor(n)} key={n}>×{fmt(n)}</button>)}</div></div><p className="muted small-text">Время и температура не изменяются при пересчёте.</p></div>{cooking&&<><div className="part-tabs no-print">{detail.parts.map((p:Part,i:number)=><button className={activePart===i?'selected':''} key={p.id} onClick={()=>setActivePart(i)}>{p.name}</button>)}</div><p className="muted">Выполнено шагов: {checks.length}. На поддерживаемых устройствах экран остаётся включённым.</p></>}{detail.parts.filter((_:any,i:number)=>!cooking||activePart===i).map((p:Part)=><section className="detail-part" key={p.id}><h2>{p.name}</h2>{p.sourceId&&<p className="source-note"><Layers size={14}/>Сохранённая версия компонента · {p.sourceRevision}</p>}<div className="ingredients-view"><div className="ingredients-heading"><b>Ингредиент</b><span>Исходное</span><strong>×{fmt(factor)}</strong></div>{p.ingredients.map((i:Ingredient,j:number)=><div className="ingredient-row" key={j}><span>{i.name}<small>{i.note}</small></span><span>{fmt(i.qty)} {i.unit}</span><strong>{fmt(i.qty*factor)} {i.unit}</strong></div>)}</div><div className="temperature-line">{p.temperature&&<span>Температура: {p.temperature}</span>}{p.time&&<span><Clock size={14}/> {p.time}</span>}</div><h3>Технология приготовления</h3><ol className="steps">{p.steps.map((s:string,i:number)=><li key={i} className={checks.includes(p.id+'-'+i)?'done':''}><button className="step-number" aria-label={'Отметить шаг '+(i+1)} onClick={()=>setChecks(checks.includes(p.id+'-'+i)?checks.filter(v=>v!==p.id+'-'+i):[...checks,p.id+'-'+i])}>{checks.includes(p.id+'-'+i)?<Check size={16}/>:i+1}</button><p>{s.split(/(\*\*.*?\*\*)/g).map((v,j)=>v.startsWith('**')?<strong key={j}>{v.slice(2,-2)}</strong>:v)}</p></li>)}</ol>{p.photos?.length?<div className="gallery">{p.photos.map((url:string,i:number)=><img src={url} key={i} alt="Этап приготовления" onClick={()=>setLightbox(url)}/>)}</div>:null}{p.notes&&<div className="notes">{p.notes}</div>}</section>)}{(detail.storage||detail.shelfLife)&&<div className="notes"><h3>Хранение</h3>{detail.storage} {detail.shelfLife&&' · '+detail.shelfLife}</div>}{detail.notes&&<div className="notes"><h3>Авторские заметки</h3>{detail.notes}</div>}{detail.photos?.length?<div className="gallery">{detail.photos.map((url:string,i:number)=><img src={url} key={i} alt={'Фото десерта '+(i+1)} onClick={()=>setLightbox(url)}/>)}</div>:null}<div className="detail-dates">Создан: {date(detail.created)} · Изменён: {date(detail.updated)}</div><div className="no-print"><Button disabled={busy||factor<=0} onClick={()=>addToShopping([{recipe:detail,factor}])}><ShoppingBasket size={17}/>Ингредиенты в покупки</Button><p className="muted small-text">{list?'Добавить в список «'+list.name+'»':'Будет создан новый список покупок'}</p><button className="text-link" onClick={()=>window.print()}><Printer size={16}/>Распечатать / сохранить в PDF</button></div></div></article></div>}
{importOpen&&<div className="modal-backdrop"><div className="modal compact" role="dialog" aria-modal="true" aria-label="Импорт рецепта"><div className="modal-head"><h2>Импорт рецепта</h2><button className="icon-btn" aria-label="Закрыть" onClick={()=>setImportOpen(false)}><X size={22}/></button></div><div className="modal-content"><p>Вставьте текст: название на первой строке, затем компоненты, ингредиенты и технология. Например: «Сливки 33% — 250 г».</p><textarea rows={12} placeholder="Название рецепта&#10;Крем:&#10;Сливки 33% — 250 г&#10;Белый шоколад — 150 г&#10;Нагреть сливки…" value={importText} onChange={e=>setImportText(e.target.value)}/><div className="notice">Распознавание текста выполняется по правилам, без ИИ. Проверьте количества и структуру перед сохранением. Нераспознанные строки останутся в технологии.</div><label className="upload-btn"><Upload size={16}/>Открыть текстовый файл<input type="file" accept=".txt,text/plain" onChange={async e=>{const f=e.target.files?.[0];if(f)setImportText(await f.text())}}/></label><div className="import-files"><Upload size={27} strokeWidth={1}/><b>Импорт PDF, JPG и PNG</b><p>Текст из PDF извлекается на вашем устройстве. Для фотографий и сканированных PDF необходимо подключить сервис OCR. После извлечения проверьте результат в редакторе.</p><input type="file" accept="application/pdf,image/jpeg,image/png" onChange={async e=>{const f=e.target.files?.[0];if(f?.type==='application/pdf'){setBusy(true);try{setImportText(await extractPdf(f));tell('Текст извлечён. Нажмите «Распознать и проверить».')}catch(err:any){tell(err.message||'Не удалось прочитать PDF')}finally{setBusy(false)}}else if(f)tell('Для распознавания фотографий необходимо подключить сервис OCR');e.target.value=''}}/></div></div><div className="modal-footer"><Button disabled={!importText.trim()} onClick={()=>{setEditor(parseText(importText));setImportOpen(false);tell('Предварительный результат готов. Проверьте перед сохранением.')}}>Распознать и проверить <ArrowRight size={16}/></Button></div></div></div>}
{recipePicker&&<div className="modal-backdrop"><div className="modal compact" role="dialog" aria-modal="true" aria-label="Выбор рецептов"><div className="modal-head"><h2>Соберём всё необходимое</h2><button className="icon-btn" aria-label="Закрыть" onClick={()=>setRecipePicker(false)}><X size={22}/></button></div><div className="modal-content"><p className="muted">Выберите рецепты и укажите необходимое количество порций / изделий. Совместимые единицы объединятся автоматически.</p>{!ownRecipes.length?<Empty title="Сначала сохраните рецепт" text="В покупки попадут ингредиенты из вашей личной коллекции."/>:ownRecipes.map(r=><div className="picker-row" key={r.id}><input aria-label={'Выбрать '+r.name} type="checkbox" checked={r.id in chosen} onChange={e=>{const n={...chosen};if(e.target.checked)n[r.id]=r.servings||1;else delete n[r.id];setChosen(n)}}/><div><b>{r.name}</b><small>Исходный выход: {r.servings} · {r.parts.length} компонентов</small></div><input aria-label={'Порций: '+r.name} type="number" min="0.000001" step="any" disabled={!(r.id in chosen)} value={chosen[r.id]??r.servings} onChange={e=>setChosen({...chosen,[r.id]:num(e.target.value)})}/></div>)}</div><div className="modal-footer"><Button disabled={!Object.keys(chosen).length||busy||Object.values(chosen).some(n=>n<=0||!Number.isFinite(n))} onClick={()=>addToShopping(ownRecipes.filter(r=>r.id in chosen).map(r=>({recipe:r,factor:chosen[r.id]/(r.servings||1)})))}>Сформировать список <ArrowRight size={16}/></Button></div></div></div>}
{restore&&<div className="modal-backdrop"><div className="modal compact"><div className="modal-head"><h2>Восстановление коллекции</h2><button className="icon-btn" aria-label="Закрыть" onClick={()=>setRestore(null)}><X size={22}/></button></div><div className="modal-content"><p>В копии {restore.length} записей. Будут созданы новые копии рецептов, компонентов, списков и разработок. Текущие записи и настройки останутся на месте.</p><Button disabled={busy} onClick={async()=>{const map=new Map(restore.map(r=>[r.id,uid()]));let count=0;for(const r of restore.filter(r=>r.kind!=='settings')){const v=copy(r);v.id=map.get(r.id)!;delete v.revision;for(const p of v.parts||[])if(p.sourceId)p.sourceId=map.get(p.sourceId)||p.sourceId;if(v.approved)v.approved=map.get(v.approved)||v.approved;const result=await save(v,true);if(!result){tell('Восстановлено '+count+' записей. Процесс остановлен из-за ошибки.');return}count++}setRestore(null);tell('Восстановлено записей: '+count)}}>Восстановить копии</Button></div></div></div>}
{confirm&&<div className="modal-backdrop confirm-layer"><div className="modal confirmation" role="alertdialog" aria-modal="true"><h2>Подтвердите действие</h2><p>{confirm.text}</p><div className="flex end"><Button soft onClick={()=>setConfirm(null)}>Отмена</Button><Button onClick={()=>{const fn=confirm.action;setConfirm(null);fn()}}>Подтвердить</Button></div></div></div>}
{lightbox&&<div className="lightbox" role="dialog" aria-modal="true" aria-label="Фотография" onClick={()=>setLightbox('')}><button aria-label="Закрыть фото"><X size={27}/></button><img src={lightbox} alt="Фотография в полном размере"/></div>}
</div>}
function PartEditor({p,index,total,units,onChange,onMove,onDelete,UploadField}:any){const updateIngredient=(j:number,key:string,value:any)=>onChange({...p,ingredients:p.ingredients.map((v:Ingredient,i:number)=>i===j?{...v,[key]:value}:v)});return <section className="part-editor"><div className="part-editor-head"><span className="part-index">{String(index+1).padStart(2,'0')}</span><input aria-label="Название компонента" required value={p.name} onChange={e=>onChange({...p,name:e.target.value})}/><div className="flex"><button type="button" className="icon-btn" aria-label="Переместить выше" disabled={index===0} onClick={()=>onMove(-1)}><ArrowUp size={16}/></button><button type="button" className="icon-btn" aria-label="Переместить ниже" disabled={index===total-1} onClick={()=>onMove(1)}><ArrowDown size={16}/></button><button type="button" className="icon-btn" aria-label="Удалить компонент" onClick={onDelete}><Trash2 size={16}/></button></div></div>{p.sourceId&&<p className="source-note"><Layers size={14}/>Копия компонента из библиотеки · версия {p.sourceRevision}. Изменения оригинала не повлияют на рецепт.</p>}<div className="ingredient-table"><div className="ingredient-labels"><span>Ингредиент</span><span>Количество</span><span>Ед.</span><span>Примечание</span><span/></div>{p.ingredients.map((i:Ingredient,j:number)=><div className="ingredient-inputs" key={j}><input aria-label="Ингредиент" required placeholder="Например, сливки 33%" value={i.name} onChange={e=>updateIngredient(j,'name',e.target.value)}/><input aria-label="Количество ингредиента" required type="number" min="0" step="any" value={i.qty} onChange={e=>updateIngredient(j,'qty',num(e.target.value))}/><select aria-label="Единица измерения ингредиента" value={i.unit} onChange={e=>updateIngredient(j,'unit',e.target.value)}>{units.map((u:string)=><option key={u}>{u}</option>)}</select><input aria-label="Примечание к ингредиенту" placeholder="Необязательно" value={i.note} onChange={e=>updateIngredient(j,'note',e.target.value)}/><button type="button" className="icon-btn" aria-label="Удалить ингредиент" onClick={()=>onChange({...p,ingredients:p.ingredients.filter((_:any,k:number)=>j!==k)})}><X size={15}/></button></div>)}</div><button type="button" className="text-link add-row" onClick={()=>onChange({...p,ingredients:[...p.ingredients,ingredient()]})}><Plus size={15}/>Добавить ингредиент</button><h3>Технология приготовления</h3><p className="muted small-text">Для важного момента используйте **две звёздочки** с обеих сторон.</p>{p.steps.map((s:string,j:number)=><div className="step-editor" key={j}><span>{j+1}</span><textarea aria-label={'Шаг '+(j+1)} rows={2} value={s} onChange={e=>onChange({...p,steps:p.steps.map((v:string,k:number)=>j===k?e.target.value:v)})} placeholder="Опишите этап приготовления"/><div className="step-controls"><button type="button" className="icon-btn" aria-label="Шаг выше" disabled={!j} onClick={()=>{const steps=[...p.steps];[steps[j],steps[j-1]]=[steps[j-1],steps[j]];onChange({...p,steps})}}><ArrowUp size={14}/></button><button type="button" className="icon-btn" aria-label="Шаг ниже" disabled={j===p.steps.length-1} onClick={()=>{const steps=[...p.steps];[steps[j],steps[j+1]]=[steps[j+1],steps[j]];onChange({...p,steps})}}><ArrowDown size={14}/></button><button type="button" className="icon-btn" aria-label="Удалить шаг" onClick={()=>onChange({...p,steps:p.steps.filter((_:any,k:number)=>j!==k)})}><X size={14}/></button></div></div>)}<button type="button" className="text-link add-row" onClick={()=>onChange({...p,steps:[...p.steps,'']})}><Plus size={15}/>Добавить шаг</button><div className="form-grid"><Field label="Температура"><input placeholder="Например, 170 °C" value={p.temperature} onChange={e=>onChange({...p,temperature:e.target.value})}/></Field><Field label="Время"><input placeholder="Например, 20 минут" value={p.time} onChange={e=>onChange({...p,time:e.target.value})}/></Field></div><Field label="Заметки к компоненту"><textarea value={p.notes} onChange={e=>onChange({...p,notes:e.target.value})}/></Field><div className="photo-editor">{(p.photos||[]).map((url:string,i:number)=><div className="photo-thumb" key={i}><img src={url} alt="Этап приготовления"/><button type="button" aria-label="Удалить фото этапа" onClick={()=>onChange({...p,photos:p.photos.filter((_:any,j:number)=>j!==i)})}><X size={13}/></button></div>)}<UploadField label="Фото этапов компонента" onPhoto={(url:string)=>onChange({...p,photos:[...(p.photos||[]),url]})}/></div><Field label="Количество компонента: коэффициент"><input type="number" min="0.000001" step="any" defaultValue="1" onBlur={e=>{const f=num(e.target.value);if(f>0&&Number.isFinite(f)&&f!==1)onChange({...p,ingredients:p.ingredients.map((i:Ingredient)=>({...i,qty:i.qty*f}))});e.target.value='1'}}/></Field></section>}

function PasswordForm({tell}:any){const [pending,setPending]=useState(false);return <form onSubmit={async e=>{e.preventDefault();const form=e.currentTarget;const data=new FormData(form);setPending(true);try{const r=await fetch('/api/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({current:data.get('current'),password:data.get('password')})});const v:any=await r.json();if(!r.ok)throw Error(v.error);form.reset();tell('Пароль изменён. Другие сеансы завершены.')}catch(err:any){tell(err.message)}finally{setPending(false)}}}><h3>Сменить пароль</h3><Field label="Текущий пароль"><input name="current" type="password" autoComplete="current-password" required/></Field><Field label="Новый пароль — минимум 12 символов"><input name="password" type="password" minLength={12} autoComplete="new-password" required/></Field><Button type="submit" soft disabled={pending}>Сохранить пароль</Button></form>}
